-- Generated by scripts/gen_mvp_weeks.py — Project Physics week inputs (the app is the packet).
-- Idempotent: blocks with ids starting <prefix>d / <prefix>- are stripped, then re-appended.

update public.lessons set content_blocks = jsonb_set(content_blocks, '{blocks}',
  (select coalesce(jsonb_agg(b order by o), '[]'::jsonb) from jsonb_array_elements(content_blocks->'blocks') with ordinality as x(b,o)
     where (b->>'id') not like 'w00d%' and (b->>'id') not like 'w00-%')
  || $$[{"id": "w00d2", "type": "callout", "variant": "tip", "title": "Day 2 · The detector · first touch · Día 2 · El detector · primer contacto", "markdown": "**HANDS · MANOS (25 min) — first, always.** Vernier motion detector on the table. One at a time: walk toward it slowly, away fast, stop. Watch the trace before anyone explains it. · Detector de movimiento Vernier en la mesa. Uno a la vez: camina hacia él despacio, aléjate rápido, detente. Mira la traza antes de que alguien la explique.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d2-trace", "type": "sketch", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "instruction": "RECORD · Sketch what the screen showed for YOUR walk. Label where you walked toward, away, and stopped — in either language. · REGISTRA · Dibuja lo que mostró la pantalla en TU caminata. Marca dónde caminaste hacia, lejos y parado — en cualquier idioma.", "prompts": ["One line for the whole walk · Una línea para toda la caminata", "Label toward / away / stopped · Marca hacia / lejos / parado", "Mark where you were fastest · Marca dónde ibas más rápido"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "REGISTRA · Dibuja lo que mostró la pantalla en TU caminata. Marca dónde caminaste hacia, lejos y parado — en cualquier idioma."}, "labelBank": ["toward · hacia", "away · lejos", "stopped · parado", "fast · rápido", "slow · lento", "start · inicio"], "modes": ["sketch"]}}, {"id": "w00d2-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** When the line went UP, which way were you walking? How do you know? · Cuando la línea SUBIÓ, ¿hacia dónde caminabas? ¿Cómo lo sabes?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d2-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "When I walked ___, the line went ___. When I stopped, the line was ___.", "wordBank": ["toward · hacia", "away · lejos", "up · sube", "down · baja", "flat · plana", "steep · empinada"], "frames": [{"level": 1, "text": "When I walked [toward / away], the line went [up / down]. Stopped = [flat].", "text_l1": {"es": "Cuando caminé [hacia / lejos], la línea [subió / bajó]. Parado = [plana]."}}, {"level": 2, "text": "When I walked ___, the line went ___ because ___.", "text_l1": {"es": "Cuando caminé ___, la línea ___ porque ___."}}, {"level": 3, "text": "The trace showed ___", "text_l1": {"es": "La traza mostró ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · lo que te dijo la traza"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · what the trace told you"}, {"id": "w00d3", "type": "callout", "variant": "tip", "title": "Day 3 · Teams, roles, the timeline · Día 3 · Equipos, roles, la línea de tiempo", "markdown": "**HANDS · MANOS (25 min) — first, always.** Groups of three with one bridge. Roles: hands · recorder · reporter — they rotate every block. Build something in 10 minutes from what is on the table, then open your first timeline entry. · Grupos de tres con un «puente». Roles: manos · registrador · reportero — rotan cada bloque. Construyan algo en 10 minutos con lo que hay en la mesa, luego abran su primera entrada de la línea de tiempo.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d3-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #1 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #1 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w00d3-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** What is one thing your team planned that did NOT happen? Why? · ¿Qué cosa planeó tu equipo que NO pasó? ¿Por qué?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d4", "type": "callout", "variant": "tip", "title": "Day 4 · Paper tower · predict before you test · Día 4 · Torre de papel · predice antes de probar", "markdown": "**HANDS · MANOS (25 min) — first, always.** Twenty minutes, 10 sheets of paper, 30 cm of tape. Before you build: LOCK a prediction of the height. The prediction is graded for the reasoning, never for being right. · Veinte minutos, 10 hojas de papel, 30 cm de cinta. Antes de construir: FIJA una predicción de la altura. La predicción se califica por el razonamiento, nunca por acertar.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d4-predict", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "I predict our tower will be ___ cm tall, because ___. Evidence that would prove me wrong: ___.", "wordBank": ["taller · más alta", "shorter · más baja", "wide base · base ancha", "folds · dobleces", "tape · cinta", "because · porque"], "frames": [{"level": 1, "text": "I predict ___ cm.", "text_l1": {"es": "Predigo ___ cm."}}, {"level": 2, "text": "I predict ___ cm because ___.", "text_l1": {"es": "Predigo ___ cm porque ___."}}, {"level": 3, "text": "I predict ___ cm because ___. I would be wrong if ___.", "text_l1": {"es": "Predigo ___ cm porque ___. Estaría equivocado si ___."}}], "sei": {"prompt_l1": {"es": "PREDICE (fijada) · antes de que alguien toque el papel"}, "talkFirst": true, "visual": {"src": "/images/sei/2026-xj-approach.svg", "alt": "Earth and the approaching object 2026-XJ."}, "modes": ["text"]}, "note": "PREDICT (locked) · before anyone touches the paper", "gate": true}, {"id": "w00d4-data", "type": "data_table", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "columns": ["Predicted height (cm) · Predicción", "Actual height (cm) · Real", "Gap (cm) · Diferencia"], "rows": 1, "plot": false, "patternPrompt": "Was your prediction high or low? By how much? · ¿Tu predicción fue alta o baja? ¿Por cuánto?", "sei": {"prompt_l1": {"es": "¿Tu predicción fue alta o baja? ¿Por cuánto?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w00d4-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Whose tower beat its prediction? What did they do that you did not? · ¿Qué torre superó su predicción? ¿Qué hicieron que tú no?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d4-gap", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "We predicted ___ cm. Our tower was ___ cm. The gap is because ___.", "wordBank": ["fell over · se cayó", "base · base", "ran out of tape · se acabó la cinta", "stronger fold · doblez más fuerte", "higher than · más alta que", "lower than · más baja que"], "frames": [{"level": 1, "text": "Predicted ___ cm. Actual ___ cm. [Higher / lower].", "text_l1": {"es": "Predicción ___ cm. Real ___ cm. [Más alta / más baja]."}}, {"level": 2, "text": "We predicted ___ cm and got ___ cm. The gap is because ___.", "text_l1": {"es": "Predijimos ___ cm y obtuvimos ___ cm. La diferencia es porque ___."}}, {"level": 3, "text": "Gap: ___ — because ___", "text_l1": {"es": "Diferencia: ___ — porque ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · la diferencia"}, "talkFirst": true, "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "Planned, actual, why the gap."}, "modes": ["text"]}, "note": "WRITE · the gap"}, {"id": "w00d4-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #2 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #2 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w00-exit", "type": "exit_ticket", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "talkFirst": true, "prompt": "EXIT · Week 0 · What will you do differently on the next build — and what prediction will you lock first?", "frame": "Next build I will ___. First I will predict ___.", "sei": {"prompt_l1": {"es": "SALIDA · Semana 0 · ¿Qué harás diferente en la próxima construcción — y qué predicción fijarás primero?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Next build I will [test first / plan the base / write the number].", "text_l1": {"es": "La próxima vez voy a [probar primero / planear la base / escribir el número]."}}, {"level": 2, "text": "Next build I will ___ because ___. First I will predict ___.", "text_l1": {"es": "La próxima vez haré ___ porque ___. Primero predeciré ___."}}, {"level": 3, "text": "Next time: ___", "text_l1": {"es": "La próxima vez: ___"}}], "wordBank": ["plan · planear", "test · probar", "measure · medir", "predict · predecir", "because · porque"], "visual": {"src": "/images/sei/2026-xj-approach.svg", "alt": "Earth and the approaching object 2026-XJ."}, "modes": ["text", "sketch"]}}, {"id": "w00-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w00.predict-lock", "pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target of the week. Opens after the exit ticket on lobby days (MC-6)."}]$$::jsonb), updated_at = now()
where slug = 'pp-w00';

update public.lessons set content_blocks = jsonb_set(content_blocks, '{blocks}',
  (select coalesce(jsonb_agg(b order by o), '[]'::jsonb) from jsonb_array_elements(content_blocks->'blocks') with ordinality as x(b,o)
     where (b->>'id') not like 'w01d%' and (b->>'id') not like 'w01-%')
  || $$[{"id": "w01d1", "type": "callout", "variant": "tip", "title": "Day 1 · Walk the graph · Día 1 · Camina la gráfica", "markdown": "**HANDS · MANOS (25 min) — first, always.** Motion detector + the graph-matching screen. Walk to match three graphs. Then the reverse: sketch the graph of a walk BEFORE the screen draws it. · Detector de movimiento + pantalla de emparejar gráficas. Camina para igualar tres gráficas. Luego al revés: dibuja la gráfica de una caminata ANTES de que la pantalla la dibuje.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d1-predict", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "PREDICT · Sketch the position–time graph of this walk BEFORE you do it: stand 1 m away, walk away slowly for 3 s, stop for 2 s, walk back fast. · PREDICE · Dibuja la gráfica posición–tiempo de esta caminata ANTES de hacerla: párate a 1 m, aléjate despacio 3 s, detente 2 s, regresa rápido.", "prompts": ["Start 1 m from the detector · Empieza a 1 m", "Away slowly = gentle up · Lejos despacio = sube suave", "Stop = flat · Parado = plana", "Back fast = steep down · Regresa rápido = baja empinada"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "PREDICE · Dibuja la gráfica posición–tiempo de esta caminata ANTES de hacerla: párate a 1 m, aléjate despacio 3 s, detente 2 s, regresa rápido."}, "labelBank": ["away · lejos", "toward · hacia", "stopped · parado", "slow · lento", "fast · rápido", "steep · empinada"], "modes": ["sketch"]}}, {"id": "w01d1-scores", "type": "data_table", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "columns": ["Graph · Gráfica", "Match score (%) · Puntaje", "What I fixed · Qué corregí"], "rows": 3, "plot": false, "patternPrompt": "Which part of a graph was hardest to walk? Why? · ¿Qué parte de la gráfica fue más difícil de caminar? ¿Por qué?", "sei": {"prompt_l1": {"es": "¿Qué parte de la gráfica fue más difícil de caminar? ¿Por qué?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d1-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Show your partner your sketch and the screen. Where do they disagree, and who was right? · Muestra a tu pareja tu dibujo y la pantalla. ¿Dónde no coinciden, y quién tenía razón?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d1-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "frame": "When the line goes UP, I am walking ___. When it is FLAT, I am ___. When it is STEEP, I am going ___.", "wordBank": ["away · lejos", "toward · hacia", "stopped · parado", "faster · más rápido", "slower · más lento", "steady · constante"], "frames": [{"level": 1, "text": "Up = [away / toward]. Flat = [stopped / steady]. Steep = [faster / slower].", "text_l1": {"es": "Sube = [lejos / hacia]. Plana = [parado / constante]. Empinada = [más rápido / más lento]."}}, {"level": 2, "text": "When the line goes up I am walking ___; flat means ___; steep means ___.", "text_l1": {"es": "Cuando la línea sube camino ___; plana significa ___; empinada significa ___."}}, {"level": 3, "text": "In my words: ___", "text_l1": {"es": "Con mis palabras: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · lee la gráfica"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · read the graph"}, {"id": "w01d2", "type": "callout", "variant": "tip", "title": "Day 2 · Sims that CHECK, never draw first · Día 2 · Sims que COMPRUEBAN, nunca dibujan primero", "markdown": "**HANDS · MANOS (25 min) — first, always.** Two sims. Rule: write your predicted graph shape in the table, THEN run the sim. Fix your prediction in the third column — the fix is the learning. · Dos sims. Regla: escribe la forma de la gráfica que predices en la tabla, LUEGO corre el sim. Corrige tu predicción en la tercera columna — la corrección es el aprendizaje.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d2-sim1", "type": "sim_embed", "simulationSlug": "constant-velocity"}, {"id": "w01d2-check", "type": "data_table", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "columns": ["Motion I set · Movimiento que puse", "Predicted x–t shape · Forma predicha", "What the sim drew · Lo que dibujó", "My fix · Mi corrección"], "rows": 3, "plot": false, "patternPrompt": "What did you predict wrong most often — the direction, the steepness, or the flat parts? · ¿Qué predijiste mal más seguido — la dirección, la inclinación o las partes planas?", "sei": {"prompt_l1": {"es": "¿Qué predijiste mal más seguido — la dirección, la inclinación o las partes planas?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d2-sim2", "type": "sim_embed", "simulationSlug": "uniformly-accelerated-motion"}, {"id": "w01d2-vt", "type": "question", "capture": true, "targetId": "pp.w01.a-from-slope", "xp": 5, "question": {"prompt": "On a VELOCITY–time graph the line is flat, above zero. What is the object doing?", "options": [{"id": "steady", "icon": "➡", "text": "Moving at a steady speed — the velocity is not changing", "text_l1": {"es": "Moviéndose a rapidez constante — la velocidad no cambia"}, "feedback": "Yes. Flat on a v–t graph means constant velocity. (Flat on an x–t graph meant stopped — different graph, different meaning.) · Sí: plana en v–t es velocidad constante."}, {"id": "stopped", "icon": "🛑", "text": "Stopped", "text_l1": {"es": "Detenido"}, "feedback": "That is what flat means on a POSITION graph. Here the flat line is above zero — the velocity is a steady non-zero number. · Eso es lo que significa plana en una gráfica de POSICIÓN. Aquí la línea está arriba de cero."}, {"id": "faster", "icon": "📈", "text": "Speeding up", "text_l1": {"es": "Acelerando"}, "feedback": "Speeding up would be a line going UP on v–t. Flat means the speed stays the same. · Acelerar sería una línea que SUBE en v–t."}], "correctOptionId": "steady", "explain": "Say the rule for x–t and the rule for v–t in one sentence each. · Di la regla para x–t y la regla para v–t, una oración cada una."}, "sei": {"prompt_l1": {"es": "En una gráfica VELOCIDAD–tiempo la línea es plana, arriba de cero. ¿Qué hace el objeto?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Flat on x–t = [stopped]. Flat on v–t = [steady speed].", "text_l1": {"es": "Plana en x–t = [parado]. Plana en v–t = [rapidez constante]."}}, {"level": 2, "text": "On x–t, flat means ___. On v–t, flat means ___, because ___.", "text_l1": {"es": "En x–t, plana significa ___. En v–t, plana significa ___, porque ___."}}], "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["choice"]}, "gate": true}, {"id": "w01d2-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Which graph is which? Explain to your partner how you tell an x–t graph from a v–t graph without reading the label. · ¿Cuál gráfica es cuál? Explícale a tu pareja cómo distingues una gráfica x–t de una v–t sin leer la etiqueta.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d3", "type": "callout", "variant": "tip", "title": "Day 3 · A number out of a graph · slope and area · Día 3 · Un número de una gráfica · pendiente y área", "markdown": "**HANDS · MANOS (25 min) — first, always.** Slope calculator first: drag two points on an x–t graph, read the slope, say what it means. Then area under a v–t curve. These are the two moves every build this year will use. · Primero la calculadora de pendiente: arrastra dos puntos en una gráfica x–t, lee la pendiente, di qué significa. Luego el área bajo una curva v–t. Estos son los dos movimientos que usará cada construcción este año.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d3-sim1", "type": "sim_embed", "simulationSlug": "slope-calculator"}, {"id": "w01d3-gewa1", "type": "gewa", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "prompt": "A cart is at 2.0 m at t = 1.0 s and at 3.0 m at t = 5.0 s. Use the slope of its position–time graph to find its velocity. · Un carrito está en 2.0 m en t = 1.0 s y en 3.0 m en t = 5.0 s. Usa la pendiente de su gráfica posición–tiempo para hallar su velocidad.", "givenHint": "two positions and two times · dos posiciones y dos tiempos", "equationHint": "v = Δx / Δt  (rise over run · elevación sobre avance)", "solveFor": "v", "equationIds": ["avg-velocity", "avg-speed", "displacement", "avg-acceleration"], "sei": {"prompt_l1": {"es": "Halla la velocidad desde la pendiente: v = Δx / Δt."}, "tier2Terms": ["slope"]}}, {"id": "w01d3-sim2", "type": "sim_embed", "simulationSlug": "area-under-curve"}, {"id": "w01d3-gewa2", "type": "gewa", "capture": true, "targetId": "pp.w01.area", "xp": 5, "prompt": "A cart moves at a steady 0.40 m/s for 6.0 s. Use the area under its velocity–time graph to find how far it went. · Un carrito se mueve a 0.40 m/s constantes durante 6.0 s. Usa el área bajo su gráfica velocidad–tiempo para hallar cuánto avanzó.", "givenHint": "a velocity and a time · una velocidad y un tiempo", "equationHint": "Δx = v · Δt  (area of the rectangle · área del rectángulo)", "solveFor": "Δx", "equationIds": ["displacement", "avg-velocity", "avg-speed", "avg-acceleration"], "sei": {"prompt_l1": {"es": "Halla el desplazamiento desde el área: Δx = v · Δt."}, "tier2Terms": ["area"]}}, {"id": "w01d3-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Slope or area — which one gives you a velocity, and which one gives you a distance? Why does that make sense? · Pendiente o área — ¿cuál te da una velocidad y cuál una distancia? ¿Por qué tiene sentido?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d3-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "frame": "The SLOPE of a position–time graph tells me ___. The AREA under a velocity–time graph tells me ___.", "wordBank": ["velocity · velocidad", "how far · cuánto avanzó", "displacement · desplazamiento", "steeper = faster · más empinada = más rápido", "rise over run · elevación sobre avance", "rectangle · rectángulo"], "frames": [{"level": 1, "text": "Slope → [velocity / distance]. Area → [velocity / distance].", "text_l1": {"es": "Pendiente → [velocidad / distancia]. Área → [velocidad / distancia]."}}, {"level": 2, "text": "The slope tells me ___ because ___. The area tells me ___ because ___.", "text_l1": {"es": "La pendiente me dice ___ porque ___. El área me dice ___ porque ___."}}, {"level": 3, "text": "Slope: ___ · Area: ___", "text_l1": {"es": "Pendiente: ___ · Área: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · los dos movimientos, con tus palabras"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · the two moves, in your own words"}, {"id": "w01d4", "type": "callout", "variant": "tip", "title": "Day 4 · A real cart on the track · Día 4 · Un carrito real en la pista", "markdown": "**HANDS · MANOS (25 min) — first, always.** Cart on the track, motion detector at one end. Before every push: sketch the graph you expect. Three runs — slow push, fast push, push then catch. · Carrito en la pista, detector en un extremo. Antes de cada empujón: dibuja la gráfica que esperas. Tres corridas — empujón lento, rápido, empujar y atrapar.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d4-predict", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "PREDICT · Sketch the position–time graph for run 2 (fast push, cart rolls to the end) BEFORE you push. · PREDICE · Dibuja la gráfica posición–tiempo de la corrida 2 (empujón rápido, el carrito rueda hasta el final) ANTES de empujar.", "prompts": ["Where does it start? · ¿Dónde empieza?", "Steep or gentle? · ¿Empinada o suave?", "Does it slow down? · ¿Frena?"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "PREDICE · Dibuja la gráfica posición–tiempo de la corrida 2 (empujón rápido, el carrito rueda hasta el final) ANTES de empujar."}, "labelBank": ["start · inicio", "end · final", "steep · empinada", "slowing · frenando", "steady · constante"], "modes": ["sketch"]}}, {"id": "w01d4-data", "type": "data_table", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "columns": ["Run · Corrida", "Start x (m)", "End x (m)", "Time (s) · Tiempo", "Velocity = Δx/Δt (m/s)"], "rows": 3, "plot": false, "patternPrompt": "Which run had the biggest slope? Does the number agree with what you saw? · ¿Qué corrida tuvo la pendiente más grande? ¿El número coincide con lo que viste?", "sei": {"prompt_l1": {"es": "¿Qué corrida tuvo la pendiente más grande? ¿El número coincide con lo que viste?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d4-compare", "type": "observation", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "patternPrompt": "RECORD · Where did the detector's graph match your sketch, and where did it not?", "interpretPrompt": "FIX · What will you draw differently next time, and why?", "patternFrame": "My sketch matched at ___. It was wrong at ___.", "comparatives": ["start · inicio", "steepness · inclinación", "the end · el final", "slowing down · frenando", "flat · plana", "curve · curva"], "sei": {"prompt_l1": {"es": "REGISTRA · ¿Dónde coincidió la gráfica del detector con tu dibujo, y dónde no? · CORRIGE · ¿Qué dibujarás diferente la próxima vez, y por qué?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Matched: [start / steepness / end]. Wrong: [start / steepness / end].", "text_l1": {"es": "Coincidió: [inicio / inclinación / final]. Mal: [inicio / inclinación / final]."}}, {"level": 2, "text": "My sketch matched at ___ but was wrong at ___ because ___. Next time I will ___.", "text_l1": {"es": "Mi dibujo coincidió en ___ pero falló en ___ porque ___. La próxima vez ___."}}], "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text", "sketch"]}}, {"id": "w01d4-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** The cart slowed down at the end. What did that look like on the graph? What word do we not have yet for that? · El carrito frenó al final. ¿Cómo se vio en la gráfica? ¿Qué palabra nos falta todavía para eso?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d4-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #3 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #3 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w01d5", "type": "callout", "variant": "tip", "title": "Day 5 · The reasoning artifact · Día 5 · El artefacto de razonamiento", "markdown": "**HANDS · MANOS (25 min) — first, always.** No new hands today. Record 07 is a motion nobody in the shop has seen. Describe it segment by segment, defend every claim from the graph, then draw the graph that WOULD match a motion described in words. · Hoy no hay manos nuevas. El Registro 07 es un movimiento que nadie en el taller ha visto. Descríbelo segmento por segmento, defiende cada afirmación con la gráfica, luego dibuja la gráfica que correspondería a un movimiento descrito con palabras.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d5-fig", "type": "figure", "src": "/images/sei/mystery-xt.svg", "align": "full", "alt": "Position-time graph in four segments: A flat at 1 m for 2 s, B rising to 3 m over 2 s, C flat at 3 m for 2 s, D falling to 0 m over 2 s.", "caption": "Record 07 · four segments A–D · cuatro segmentos A–D"}, {"id": "w01d5-artifact", "type": "observation", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "patternPrompt": "ARTIFACT 1 · Describe the motion in Record 07, segment by segment (A, B, C, D): which way, how fast, stopped?", "interpretPrompt": "DEFEND · For ONE segment, say which feature of the graph proves your description (slope? flat? steepness?) and give its velocity as a number.", "patternFrame": "A: ___. B: ___. C: ___. D: ___.", "comparatives": ["stopped · parado", "away · lejos", "toward · hacia", "slope · pendiente", "faster · más rápido", "m/s"], "sei": {"prompt_l1": {"es": "ARTEFACTO 1 · Describe el movimiento del Registro 07, segmento por segmento (A, B, C, D): hacia dónde, qué tan rápido, parado? · DEFIENDE · Para UN segmento, di qué característica de la gráfica prueba tu descripción (¿pendiente? ¿plana? ¿inclinación?) y da su velocidad como número."}, "talkFirst": true, "frames": [{"level": 1, "text": "A: [stopped / away / toward]. B: [stopped / away / toward]. C: ___. D: ___.", "text_l1": {"es": "A: [parado / lejos / hacia]. B: [parado / lejos / hacia]. C: ___. D: ___."}}, {"level": 2, "text": "In segment ___ the object ___ because the slope is ___ (v = ___ m/s).", "text_l1": {"es": "En el segmento ___ el objeto ___ porque la pendiente es ___ (v = ___ m/s)."}}, {"level": 3, "text": "Claim + evidence: ___", "text_l1": {"es": "Afirmación + evidencia: ___"}}], "modes": ["text", "sketch"]}, "lobbyReady": true}, {"id": "w01d5-draw", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "ARTIFACT 2 · Draw the position–time graph that WOULD match: \"It sat still 2 m away for 2 s, moved away at a steady speed for 4 s, then came back faster than it left.\" · ARTEFACTO 2 · Dibuja la gráfica posición–tiempo que correspondería a: «Se quedó quieto a 2 m durante 2 s, se alejó a rapidez constante 4 s, luego regresó más rápido de lo que se fue».", "prompts": ["Flat first · Primero plana", "Then a steady line up · Luego una línea recta que sube", "Then steeper down · Luego baja más empinada"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "ARTEFACTO 2 · Dibuja la gráfica posición–tiempo que correspondería a: «Se quedó quieto a 2 m durante 2 s, se alejó a rapidez constante 4 s, luego regresó más rápido de lo que se fue»."}, "labelBank": ["still · quieto", "steady · constante", "faster · más rápido", "away · lejos", "back · regresa"], "modes": ["sketch"]}}, {"id": "w01d5-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Trade artifacts. Find one claim on your partner's page you could prove wrong from the graph — or say why you cannot. · Intercambien artefactos. Encuentra una afirmación en la página de tu pareja que podrías refutar con la gráfica — o di por qué no puedes.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01-exit", "type": "exit_ticket", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "talkFirst": true, "prompt": "EXIT · Week 1 · One thing about graphs that still confuses me — and one thing I can now do that I could not on Monday.", "frame": "I still get confused by ___. Now I can ___.", "sei": {"prompt_l1": {"es": "SALIDA · Semana 1 · Una cosa de las gráficas que todavía me confunde — y una cosa que ahora puedo hacer y el lunes no."}, "talkFirst": true, "frames": [{"level": 1, "text": "Confused by: [flat / steep / x–t vs v–t]. Now I can: [read / sketch / find slope].", "text_l1": {"es": "Me confunde: [plana / empinada / x–t vs v–t]. Ahora puedo: [leer / dibujar / hallar la pendiente]."}}, {"level": 2, "text": "I still get confused by ___ because ___. Now I can ___.", "text_l1": {"es": "Todavía me confunde ___ porque ___. Ahora puedo ___."}}, {"level": 3, "text": "Still: ___ · Now: ___", "text_l1": {"es": "Todavía: ___ · Ahora: ___"}}], "wordBank": ["slope · pendiente", "area · área", "flat · plana", "steep · empinada", "sketch · dibujar"], "visual": {"src": "/images/sei/mystery-xt.svg", "alt": "A position-time graph in four segments A to D: flat, rising, flat, falling to zero."}, "modes": ["text", "sketch"]}}, {"id": "w01-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.read-graph", "pp.w01.v-from-slope", "pp.w01.a-from-slope", "pp.w01.area", "pp.w01.sketch-first"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target of the week. Opens after the exit ticket on lobby days (MC-6)."}]$$::jsonb), updated_at = now()
